var minimumPerimeter = function(neededApples) {
  let low = 1n, high = 1000000n, ans = high;
  const target = BigInt(neededApples);
  while (low <= high) {
    const mid = (low + high) / 2n;
    const total = 2n * mid * (mid + 1n) * (2n * mid + 1n);
    if (total >= target) {
      ans = mid;
      high = mid - 1n;
    } else {
      low = mid + 1n;
    }
  }
  return Number(ans * 8n);
};
